-- =====================================================================
-- Seed: Chapter 2 - Tense Mastery & Time Precision (from Zero to Band 9 PDF)
-- English only, pure ASCII. Safe to re-run.
-- Run AFTER seed_grammar_modules_all.sql
-- =====================================================================
BEGIN;

UPDATE grammar_chapters SET
  title = 'Tense Mastery & Time Precision',
  position = 2,
  estimated_min = 35,
  difficulty = 2,
  band_target = 'Band 6-7 accuracy',
  summary = 'Put every verb in the right time. Five high-frequency tenses cover most IELTS Writing and Speaking, with a clear map of all twelve so nothing is a mystery.',
  content = $content${"version": 1, "blocks": [{"id": "b01", "type": "heading", "level": 2, "text": "2.1 What a tense actually is (zero assumption)"}, {"id": "b02", "type": "paragraph", "text": "Subject-verb agreement made your verbs match. Tense makes them sit in the right time. In IELTS this is not a small point of grammar; it is a matter of meaning. Writing Task 1 describes data that already happened or is happening now, Task 2 predicts and generalises, and Speaking moves constantly between past stories and future plans. Put a verb in the wrong time and you have not just made a grammar slip, you have said something untrue about when it happened. That is why examiners treat tense control as a core signal of the Band 6-to-7 jump."}, {"id": "b03", "type": "paragraph", "text": "An English tense carries two pieces of information at once: Time (past, present, or future -- when did it happen?) and Aspect (simple, continuous, perfect, or perfect continuous -- is it a whole finished event, an action in progress, an action linked to another time, or a mix?). Three times multiplied by four aspects gives the twelve tenses. Five of them do about 90 per cent of IELTS work."}, {"id": "b04", "type": "table", "headers": ["Aspect", "What it signals", "Marker word/form"], "rows": [["Simple", "a whole event, a fact, a habit", "base verb / verb+ed"], ["Continuous (progressive)", "an action in progress, unfinished", "be + verb-ing"], ["Perfect", "an action linked to a later time; before now / before then", "have/had + past participle"], ["Perfect continuous", "an action in progress up to a point, with duration", "have/had been + verb-ing"]]}, {"id": "b05", "type": "heading", "level": 2, "text": "2.2 The complete map of the twelve tenses"}, {"id": "b06", "type": "paragraph", "text": "Study the whole table once so you can recognise every form. Then move to the five that matter most for IELTS."}, {"id": "b07", "type": "table", "headers": ["Tense", "Form", "Core use", "IELTS example"], "rows": [["Present simple", "base (+s)", "facts, habits, permanent situations", "Water boils at 100C. / The graph shows..."], ["Present continuous", "am/is/are + -ing", "happening now; temporary; current trends", "Currently, remote work is increasing."], ["Present perfect", "have/has + p.p.", "past linked to now; unfinished time", "The population has grown since 2010."], ["Present perfect continuous", "have/has been + -ing", "duration of a trend up to now", "Prices have been rising for a decade."], ["Past simple", "verb+ed / irregular", "finished past with a stated time", "Between 2000 and 2010, sales rose."], ["Past continuous", "was/were + -ing", "background action in the past", "While the economy was recovering..."], ["Past perfect", "had + p.p.", "earlier of two past events", "By the time the report was published, the situation had changed."], ["Past perfect continuous", "had been + -ing", "duration before a past point", "She had been waiting for two hours."], ["Future simple", "will + base", "predictions, decisions, offers", "Sea levels will rise further."], ["Future continuous", "will be + -ing", "action in progress at a future time", "By 2030, more people will be working remotely."], ["Future perfect", "will have + p.p.", "completed by a future point", "By 2040, the population will have doubled."], ["Future perfect continuous", "will have been + -ing", "duration up to a future point", "By July, I will have been living here for a decade."]]}, {"id": "b08", "type": "heading", "level": 2, "text": "2.3 The five tenses that do 90% of IELTS work"}, {"id": "b09", "type": "paragraph", "text": "Master these five thoroughly before worrying about the rest. Almost every Task 1 description, Task 2 argument, and Speaking answer is built from them."}, {"id": "b10", "type": "heading", "level": 3, "text": "1. Present simple"}, {"id": "b11", "type": "paragraph", "text": "Facts, habits, permanent situations, and the \"voice\" of a graph or chart. Task 1 openings almost always use it: The chart shows / illustrates / compares. Task 2 uses it for general truths: Education improves life chances."}, {"id": "b12", "type": "heading", "level": 3, "text": "2. Past simple"}, {"id": "b13", "type": "paragraph", "text": "Finished past with a stated or clear time period. In Task 1, any year or closed range that is over: Between 2000 and 2010, car ownership rose steadily. In Speaking Part 2 stories, past simple carries the main events."}, {"id": "b14", "type": "heading", "level": 3, "text": "3. Present perfect"}, {"id": "b15", "type": "paragraph", "text": "A past change that reaches the present, or an unfinished time period (this year, so far, since 2010, over the past decade). The population has grown significantly since the factory opened. This is the tense most often missing from Band 6 Task 1 scripts."}, {"id": "b16", "type": "heading", "level": 3, "text": "4. Present continuous"}, {"id": "b17", "type": "paragraph", "text": "Happening now, temporary situations, and current trends marked by words like currently, at present, these days. Currently, the number of remote workers is increasing steadily."}, {"id": "b18", "type": "heading", "level": 3, "text": "5. Future simple (will)"}, {"id": "b19", "type": "paragraph", "text": "Predictions and forecasts. If current trends continue, sea levels will rise further. In Task 1, forecasts often use will or is projected / is expected to for a more academic tone."}, {"id": "b20", "type": "heading", "level": 2, "text": "2.4 Choosing the right tense in Task 1"}, {"id": "b21", "type": "paragraph", "text": "Task 1 is a pure tense-selection problem. Read the time frame on the axes, then lock the verb forms."}, {"id": "b22", "type": "table", "headers": ["What the data covers", "Tense to use", "Example"], "rows": [["A finished year or closed past range", "Past simple", "In 2010, sales peaked at 40%."], ["From a past point up to now", "Present perfect", "Sales have risen since 2010."], ["The situation right now", "Present simple / continuous", "Sales now stand at 55%. / Sales are rising."], ["A future projection", "Will / is projected to", "By 2030, sales will reach 70%."]]}, {"id": "b23", "type": "example_pair", "incorrect": "Between 2000 and 2010, car ownership has risen steadily.", "correct": "Between 2000 and 2010, car ownership rose steadily.", "why": "The range is finished (ended in 2010), so past simple -- not present perfect."}, {"id": "b24", "type": "example_pair", "incorrect": "The population increased since 2010.", "correct": "The population has increased since 2010.", "why": "\"Since 2010\" reaches to now; present perfect is required."}, {"id": "b25", "type": "heading", "level": 2, "text": "2.5 Choosing the right tense in Task 2 and Speaking"}, {"id": "b26", "type": "paragraph", "text": "Task 2 mixes general truths (present simple), past evidence (past simple / present perfect), and future consequences (will / would). Speaking Part 1 is mostly present; Part 2 is often past narrative; Part 3 returns to general and hypothetical present and future."}, {"id": "b27", "type": "heading", "level": 2, "text": "2.6 Perfect and continuous forms you should recognise"}, {"id": "b28", "type": "paragraph", "text": "You will not need all twelve constantly, but recognising them lets you read a prompt correctly and adds range when it is natural."}, {"id": "b29", "type": "paragraph", "text": "Past perfect (had + p.p.) shows which of two past events came first -- useful in Speaking Part 2: By the time the report was published, the situation had already changed. Present perfect continuous stresses duration of a trend: House prices have been rising steadily for over a decade. Future perfect projects a completed change by a future point: By 2040, the population will have doubled. Use these for genuine range, not decoration."}, {"id": "b30", "type": "l1_error_fixer", "title": "The continuous-tense trap", "body": "Two continuous-tense errors dominate Bangladeshi scripts. Both come from over-using the -ing form, partly because Bangla uses its continuous form more freely than English does.", "error_types": [{"label": "Stative verbs cannot be continuous", "incorrect": "I am knowing the answer. / He is having two cars. / I am understanding your point.", "correct": "I know the answer. / He has two cars. / I understand your point."}, {"label": "\"Since\" and \"for\" take the perfect, not plain continuous", "incorrect": "The population is increasing since 2010. / Prices are rising for the last five years.", "correct": "The population has increased / has been increasing since 2010. / Prices have been rising for the last five years."}]}, {"id": "b31", "type": "callout", "variant": "warning", "title": "Stative verbs that stay simple", "text": "Common stative verbs: know, believe, understand, mean, agree, want, need, prefer, like, love, hate, seem, appear, belong, own, contain, consist, depend, and have when it means possession. Note: some can be continuous when the meaning changes to a real action (\"He is having lunch\" = eating). But know, believe, understand, want, need, belong, seem are never continuous."}, {"id": "b32", "type": "ielts_impact", "skills": ["writing", "speaking"], "title": "Why tense control signals the Band 6-to-7 jump", "body": "A script that puts finished past data in the present perfect, or ongoing trends in the past simple, tells the examiner the candidate does not control time. That single fault is enough to keep Grammatical Range and Accuracy at Band 6 even when ideas are strong. Consistent tense choice -- past for finished years, present perfect for since/for, present for now, will for forecasts -- is one of the clearest Band 7 signals in Task 1.", "examples": {"task1": "In 2010 sales peaked; they have risen every year since and now stand at 55%. By 2030 they will reach 70%.", "task2": "Education improves life chances, and governments that have invested in schools have seen long-term gains.", "speaking": "I lived in Sylhet until 2018, and I have been living in Dhaka since then."}}, {"id": "b33", "type": "exercise_ref", "exercise_slug": "ex-2-1-tense-selection", "label": "Exercise 2.1 - Tense Selection"}, {"id": "b34", "type": "exercise_ref", "exercise_slug": "ex-2-2-task1-trends", "label": "Exercise 2.2 - Task 1 Trend Description"}]}$content$::jsonb,
  is_published = true,
  updated_at = now()
WHERE slug = 'ch2-tense-mastery';

INSERT INTO grammar_exercises (id, chapter_id, slug, title, kind, instructions, items, position, is_published)
VALUES (
  'a1000001-0001-4000-8000-000000000221',
  'a1000001-0001-4000-8000-000000000102',
  'ex-2-1-tense-selection',
  'Exercise 2.1 - Tense Selection',
  'correction',
  'Choose or supply the correct verb form. For error items, state the correction.',
  $items1$[{"id": "q1", "prompt": "Between 2000 and 2010, car ownership ______ steadily before it levelled off. (rise)", "answer": "rose", "accepted": ["rose"], "reason": "Finished past range with stated years -> past simple.", "bn_note": null}, {"id": "q2", "prompt": "The population of the city ______ significantly since the new factory opened. (grow)", "answer": "has grown", "accepted": ["has grown"], "reason": "\"Since\" links past to now -> present perfect.", "bn_note": null}, {"id": "q3", "prompt": "By the time the report was published, the situation ______ already changed. (change)", "answer": "had", "accepted": ["had", "had changed"], "reason": "Earlier of two past events -> past perfect.", "bn_note": null}, {"id": "q4", "prompt": "If current trends continue, sea levels ______ further over the next century. (rise)", "answer": "will rise", "accepted": ["will rise"], "reason": "Future prediction -> future simple.", "bn_note": null}, {"id": "q5", "prompt": "Water ______ at 100 degrees Celsius at sea level. (boil)", "answer": "boils", "accepted": ["boils"], "reason": "Scientific fact -> present simple.", "bn_note": null}, {"id": "q6", "prompt": "I ______ in Dhaka for twelve years, and I still live there now. (live)", "answer": "have lived", "accepted": ["have lived", "have been living"], "reason": "Duration from past to now -> present perfect (or perfect continuous).", "bn_note": null}, {"id": "q7", "prompt": "The company ______ its first product two decades ago. (launch)", "answer": "launched", "accepted": ["launched"], "reason": "Finished past with a stated time -> past simple.", "bn_note": null}, {"id": "q8", "prompt": "Choose the error: \"The temperature is rising by three degrees last summer.\"", "answer": "is rising should be rose", "accepted": ["is rising should be rose", "is rising -> rose", "rose"], "reason": "\"Last summer\" is finished past; past simple required.", "bn_note": null}, {"id": "q9", "prompt": "Currently, the number of remote workers ______ steadily. (increase)", "answer": "is increasing", "accepted": ["is increasing"], "reason": "\"Currently\" marks a present trend -> present continuous.", "bn_note": null}, {"id": "q10", "prompt": "Choose the error: \"I have visited London in 2019 and I enjoyed it very much.\"", "answer": "have visited should be visited", "accepted": ["have visited should be visited", "have visited -> visited", "visited"], "reason": "\"In 2019\" is a finished time; past simple, not present perfect.", "bn_note": null}, {"id": "q11", "prompt": "Over the past decade, online shopping ______ dramatically. (grow)", "answer": "has grown", "accepted": ["has grown", "has been growing"], "reason": "\"Over the past decade\" reaches to now -> present perfect.", "bn_note": null}, {"id": "q12", "prompt": "While the economy ______ , unemployment remained high. (recover)", "answer": "was recovering", "accepted": ["was recovering"], "reason": "Background past action -> past continuous.", "bn_note": null}, {"id": "q13", "prompt": "She ______ two cars and a small apartment. (have - possession)", "answer": "has", "accepted": ["has"], "reason": "Possession is stative; present simple, not continuous.", "bn_note": null}, {"id": "q14", "prompt": "Sales ______ between 2000 and 2010. (fall)", "answer": "fell", "accepted": ["fell"], "reason": "Finished past range -> past simple.", "bn_note": null}, {"id": "q15", "prompt": "The government ______ a new policy at the moment. (consider)", "answer": "is considering", "accepted": ["is considering"], "reason": "\"At the moment\" -> present continuous.", "bn_note": null}, {"id": "q16", "prompt": "He ______ the problem clearly. (understand - not continuous)", "answer": "understands", "accepted": ["understands"], "reason": "Understand is stative; present simple.", "bn_note": null}, {"id": "q17", "prompt": "By 2030, renewable energy ______ the main source of power. (be)", "answer": "will be", "accepted": ["will be"], "reason": "Future prediction for a future point -> future simple.", "bn_note": null}, {"id": "q18", "prompt": "In 2012, the figure ______ sharply. (drop)", "answer": "dropped", "accepted": ["dropped"], "reason": "Tied to a finished year -> past simple.", "bn_note": null}, {"id": "q19", "prompt": "So far this year, exports ______ by 12%. (grow)", "answer": "have grown", "accepted": ["have grown"], "reason": "\"So far this year\" reaches to now -> present perfect.", "bn_note": null}, {"id": "q20", "prompt": "Most people ______ several hours a day online. (spend - habit)", "answer": "spend", "accepted": ["spend"], "reason": "Repeated general truth / habit -> present simple.", "bn_note": null}]$items1$::jsonb,
  1,
  true
)
