INSERT INTO grammar_exercises (id, chapter_id, slug, title, kind, instructions, items, position, is_published)
VALUES (
  'a1000001-0001-4000-8000-000000000222',
  'a1000001-0001-4000-8000-000000000102',
  'ex-2-2-task1-trends',
  'Exercise 2.2 - Task 1 Trend Description',
  'essay_edit',
  'Rewrite the Task 1 trend paragraph with correct tenses for each time frame.',
  $items2$[{"id": "para1", "prompt": "Rewrite this Task 1 trend description with correct tenses. Use the data timeline: low in 1990 (~2 kg), rose through the 1990s to 5 kg by 2000, fell slightly 2005-2010, has risen every year since, now ~8 kg, projected 10 kg by 2030.\n\nDraft: In 1990, coffee consumption in Country X is low. It rises throughout the 1990s. It falls between 2005 and 2010, but it rises every year since, and it stood at 8 kilograms. Looking ahead, the figure reaches 10 kilograms by 2030.", "answer": "In 1990, coffee consumption in Country X was low, at roughly 2 kilograms per person. It then rose steadily throughout the 1990s, reaching 5 kilograms by 2000. Consumption fell slightly between 2005 and 2010, but it has risen every year since, and it now stands at about 8 kilograms per person. Looking ahead, the figure is projected to reach 10 kilograms by 2030.", "accepted": [], "reason": "Past simple for finished years/ranges (was, rose, fell); present perfect for change reaching now (has risen); present simple for current level (stands); future/projection form for 2030.", "bn_note": null, "corrections": [{"from": "is low", "to": "was low", "why": "1990 is finished past"}, {"from": "rises throughout the 1990s", "to": "rose throughout the 1990s", "why": "finished past range"}, {"from": "falls between 2005 and 2010", "to": "fell between 2005 and 2010", "why": "finished past range"}, {"from": "rises every year since", "to": "has risen every year since", "why": "reaches the present"}, {"from": "stood at 8", "to": "now stands at about 8", "why": "present situation"}, {"from": "reaches 10 kilograms by 2030", "to": "is projected to reach 10 kilograms by 2030", "why": "future forecast"}]}]$items2$::jsonb,
  2,
  true
)
ON CONFLICT (chapter_id, slug) DO UPDATE SET
